export function initialize(element, dotNetRef, timeoutMs) {
    let timerId = null;
    let isIdle = false;

    function resetTimer() {
        if (isIdle) {
            isIdle = false;
            dotNetRef.invokeMethodAsync('OnBecameActive');
        }
        clearTimeout(timerId);
        timerId = setTimeout(() => {
            isIdle = true;
            dotNetRef.invokeMethodAsync('OnBecameIdle');
        }, timeoutMs);
    }

    const events = ['mousemove', 'keydown', 'click', 'scroll'];
    events.forEach(evt => element.addEventListener(evt, resetTimer, { passive: true }));

    // Start the initial timer
    timerId = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync('OnBecameIdle');
    }, timeoutMs);

    return {
        dispose() {
            clearTimeout(timerId);
            events.forEach(evt => element.removeEventListener(evt, resetTimer));
        },
        updateTimeout(newTimeoutMs) {
            timeoutMs = newTimeoutMs;
            resetTimer();
        }
    };
}

